create or replace function public.driver_outstanding_balances(as_of date default current_date) returns table(driver_id uuid,driver_name text,outstanding_centavos bigint) language sql stable security definer set search_path=public as $$ select d.id,d.full_name,greatest(coalesce(sum(r.amount_due_centavos),0)-coalesce(sum(p.amount_centavos),0),0) from drivers d left join remittances r on r.driver_id=d.id and r.service_date<=as_of and r.deleted_at is null left join remittance_payments p on p.remittance_id=r.id and p.deleted_at is null where d.deleted_at is null and public.is_owner() group by d.id,d.full_name $$;
